package com.siam.deviceinfo.adapter; import android.view.*;import android.widget.*;import android.content.*;import android.content.pm.*;import java.util.*;import com.siam.deviceinfo.R;
public class AppAdapter extends BaseAdapter {Context c;List<ApplicationInfo> a;PackageManager p;public AppAdapter(Context c,List<ApplicationInfo>a){this.c=c;this.a=a;p=c.getPackageManager();}public int getCount(){return a.size();}public Object getItem(int i){return a.get(i);}public long getItemId(int i){return i;}public View getView(int i,View v,android.view.ViewGroup g){if(v==null)v=LayoutInflater.from(c).inflate(R.layout.item_app,g,false);ApplicationInfo x=a.get(i);((TextView)v.findViewById(R.id.app_name)).setText(p.getApplicationLabel(x));((TextView)v.findViewById(R.id.app_detail)).setText(x.packageName);return v;}}
